from queueing import payload

def submit(owner, enqueue, batch_size=20):
    # Validate batch_size before enqueue
    if not isinstance(batch_size, int):
        raise ValueError('batch_size must be an integer')
    if batch_size < 1 or batch_size > 100:
        raise ValueError('batch_size must be between 1 and 100')
    return enqueue(payload(owner, batch_size))

def execute(task, process):
    batch_size = task.get('batch_size', 20)
    # batch_size already validated before enqueue
    return process(task["owner"], batch_size)

