def test_default_batch_size():
    # mock enqueue that captures payload
    captured = []
    def enqueue(p):
        captured.append(p)
    # call submit without batch_size
    submit('owner1', enqueue)
    p = captured[0]
    assert p['owner'] == 'owner1'
    assert p['batch_size'] == 20

def test_explicit_batch_size():
    captured = []
    def enqueue(p):
        captured.append(p)
    submit('owner2', enqueue, 30)
    p = captured[0]
    assert p['owner'] == 'owner2'
    assert p['batch_size'] == 30

def test_batch_size_validation_low():
    captured = []
    def enqueue(p):
        captured.append(p)
    try:
        submit('owner3', enqueue, 0)
        assert False, 'should raise ValueError'
    except ValueError as e:
        pass

def test_batch_size_validation_high():
    captured = []
    def enqueue(p):
        captured.append(p)
    try:
        submit('owner4', enqueue, 101)
        assert False, 'should raise ValueError'
    except ValueError as e:
        pass

def test_batch_size_validation_non_int():
    captured = []
    def enqueue(p):
        captured.append(p)
    try:
        submit('owner5', enqueue, '20')
        assert False, 'should raise ValueError'
    except ValueError as e:
        pass

def test_batch_size_validation_bool():
    captured = []
    def enqueue(p):
        captured.append(p)
    try:
        submit('owner6', enqueue, True)
        assert False, 'should raise ValueError'
    except ValueError as e:
        pass

def test_worker_uses_batch_size():
    # task should contain batch_size
    task = {'owner': 'owner7', 'batch_size': 15}
    def process(owner, bs):
        return f'{owner}:{bs}'
    result = execute(task, process)
    assert result == 'owner7:15'

def test_worker_fallback_uses_20():
    # legacy payload without batch_size
    task = {'owner': 'owner8'}
    def process(owner, bs):
        return f'{owner}:{bs}'
    result = execute(task, process)
    assert result == 'owner8:20'

if __name__ == '__main__':
    test_default_batch_size()
    test_explicit_batch_size()
    test_batch_size_validation_low()
    test_batch_size_validation_high()
    test_batch_size_validation_non_int()
    test_batch_size_validation_bool()
    test_worker_uses_batch_size()
    test_worker_fallback_uses_20()
    print('All tests passed')

